import ast; import sys; from pathlib import Path; from common.meta.extension.check_package_contract import check_single_package, discover_packages; REPO = Path(__file__).resolve().parents[2]; EXTRACTION = REPO / 'apps/backend/src/extraction'; _BACKEND_ROOT = str(REPO / 'apps' / 'backend'); sys.path.insert(0, _BACKEND_ROOT) if _BACKEND_ROOT not in sys.path else None
def _imported_modules(path: Path) -> set[str]: mods: set[str] = set(); [mods.add(node.module) if isinstance(node, ast.ImportFrom) and node.module else mods.update((a.name for a in node.names)) if isinstance(node, ast.Import) else None for node in ast.walk(ast.parse(path.read_text(encoding='utf-8')))]; return mods
def test_AC_extraction_1_1_only_all_is_the_published_language(): import src.extraction as extraction_pkg; from common.extraction.contract import CONTRACT; assert sorted(CONTRACT.interface) == sorted(extraction_pkg.__all__); assert CONTRACT.name == 'extraction'; assert CONTRACT.klass == 'domain'; assert CONTRACT.implementations['be'] == 'apps/backend/src/extraction'
def test_AC_extraction_1_2_converges_by_layer():
    assert (EXTRACTION / 'base/validation.py').exists()
